#!/bin/bash
set -eo pipefail
umask 077
export PYTHONDONTWRITEBYTECODE=1 CUDA_VISIBLE_DEVICES=''
exec timeout --signal=TERM --kill-after=5s 70s /data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'LIAONING_OFFLINE_PARSE'
"""Offline, isolated public catalogue parser; no network or scientific processing."""
import base64
import datetime
import hashlib
import json
from pathlib import Path
import re
import resource
import signal
import sys
import time
import zlib

START = time.monotonic()
ROOT = Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/gap27888_liaoning_catalogue_parse_20261022_v1')
SOURCE = Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/gap27888_liaoning_catalogue_20261021_v1/CATALOGUE_RESPONSE.bin')
SOURCE_SHA = '10ca9be00113202a223e40b5a0a5239deac7a5aba4840a32d12c8c96c312d044'
WHEEL_SHA = 'ea762c3d29f4cca48d82df517b6d89fbce4db3107f9d78713e48cd321d5c9aa9'
WHEEL_BASE64 = ''
resource.setrlimit(resource.RLIMIT_AS,(512*1024**2,512*1024**2))
sys.dont_write_bytecode = True


def dump(path, raw):
    with path.open('xb') as stream:
        stream.write(raw)
        stream.flush()


def expired(signum, frame):
    raise TimeoutError('Frozen offline catalogue parsing deadline')


def stat(path):
    value = path.stat()
    return {key:getattr(value,key) for key in ('st_dev','st_ino','st_size','st_mtime_ns','st_ctime_ns')}


def record(sheet, row_index):
    cells = []
    truncated = False
    for col_index in range(min(sheet.ncols,16)):
        cell = sheet.cell(row_index,col_index)
        value = cell.value
        if isinstance(value,str) and len(value)>120:
            value = value[:120]
            truncated = True
        cells.append(dict(column_1_based=col_index+1,type_code=cell.ctype,value=value))
    return dict(sheet=sheet.name,row_1_based=row_index+1,cells=cells,
        columns_omitted=max(0,sheet.ncols-16),any_saved_cell_truncated=truncated)


def main():
    ROOT.mkdir(exist_ok=False)
    result = dict(kind='GAP27888_LIAONING_OFFLINE_PARSE',member='27888',complete=False,
        metadata_session_finished=False,requests=0,received_body_bytes=0,new_jobs=0,
        source_content_reads=0,source_decoding=0,source_writes=0,scientific_archives_downloaded=0,
        model_calls=0,automatic_checks_enabled=False,scientific_input_accepted=False,
        prediction_approved=False,source_activation_approved=False,permeability_units_verified=False,
        porosity_units_verified=False,member_coverage='UNKNOWN_NOT_SPATIALLY_COMPUTED',
        catalogue_reused=True,catalogue_parsed=False,global_environment_writes=0,
        specific_matches=[],provincial_only_matches=[],sheets=[])
    before = stat(SOURCE)
    result['source_before'] = before
    assert before['st_size'] == 785920, 'Exact existing catalogue length'
    raw = SOURCE.read_bytes()
    assert len(raw)==785920 and hashlib.sha256(raw).hexdigest()==SOURCE_SHA, 'Exact existing catalogue identity'
    result['catalogue'] = dict(path=str(SOURCE),bytes=len(raw),sha256=SOURCE_SHA)
    wheel_raw = base64.b64decode(WHEEL_BASE64,validate=True)
    assert len(wheel_raw)==96555 and hashlib.sha256(wheel_raw).hexdigest()==WHEEL_SHA, 'Exact official code wheel'
    wheel = ROOT/'xlrd-2.0.2-py2.py3-none-any.whl'
    dump(wheel,wheel_raw)
    result['runtime'] = dict(path=str(wheel),bytes=len(wheel_raw),sha256=WHEEL_SHA,installed=False)
    signal.signal(signal.SIGALRM,expired)
    signal.setitimer(signal.ITIMER_REAL,max(0.001,55-(time.monotonic()-START)))
    try:
        sys.path.insert(0,str(wheel))
        import xlrd
        assert xlrd.__version__=='2.0.2' and str(xlrd.__file__).startswith(str(wheel)+'/xlrd/'), 'Isolated runtime origin'
        result['runtime'].update(version=xlrd.__version__,module_file=str(xlrd.__file__))
        book = xlrd.open_workbook(file_contents=raw,on_demand=True)
        assert book.nsheets<=32, 'Sheet ceiling'
        specific = re.compile(r'锦州|锦县|锦西|凌海|盘锦|营口|大凌河|小凌河|下辽河|兴城|葫芦岛')
        total_specific,total_provincial = 0,0
        for sheet_index in range(book.nsheets):
            sheet = book.sheet_by_index(sheet_index)
            assert sheet.nrows<=30000 and sheet.ncols<=128, 'Catalogue shape ceiling'
            headers = []
            for row_index in range(sheet.nrows):
                assert time.monotonic()-START<55, 'Parsing elapsed ceiling'
                if row_index<2:
                    headers.append(record(sheet,row_index))
                cells = [str(sheet.cell_value(row_index,col_index)) for col_index in range(min(sheet.ncols,64))]
                text = ' | '.join(cells)
                if specific.search(text):
                    total_specific += 1
                    if len(result['specific_matches'])<200:
                        result['specific_matches'].append(record(sheet,row_index))
                elif '辽宁' in text:
                    total_provincial += 1
                    if len(result['provincial_only_matches'])<80:
                        result['provincial_only_matches'].append(record(sheet,row_index))
            result['sheets'].append(dict(name=sheet.name,rows=sheet.nrows,columns=sheet.ncols,
                searched_columns=min(sheet.ncols,64),first_two_rows=headers))
            book.unload_sheet(sheet_index)
        book.release_resources()
        result.update(catalogue_parsed=True,total_specific_matching_rows=total_specific,
            total_provincial_only_matching_rows=total_provincial,
            specific_matching_rows_omitted=max(0,total_specific-len(result['specific_matches'])),
            provincial_matching_rows_omitted=max(0,total_provincial-len(result['provincial_only_matches'])),
            catalogue_matches_are_not_spatial_coverage=True)
    except Exception as error:
        result['parse_error'] = dict(type=type(error).__name__,message=str(error)[:700])
    finally:
        signal.setitimer(signal.ITIMER_REAL,0)
    after = stat(SOURCE)
    result.update(source_after=after,source_unchanged=before==after)
    assert before==after, 'Original catalogue changed during this read'
    result.update(complete=result['catalogue_parsed'],metadata_session_finished=True,
        server_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),seconds=time.monotonic()-START)
    return result


if __name__=='__main__':
    value = main()
    body = (json.dumps(value,ensure_ascii=False,allow_nan=False,separators=(',',':'))+'\n').encode()
    assert len(body)<=4*1024**2 and time.monotonic()-START<60
    dump(ROOT/'METADATA.json',body)
    encoded = base64.b64encode(zlib.compress(body)).decode()
    assert time.monotonic()-START<60
    print('GEOLOGY_RECOVERY_BYTES='+str(len(body)))
    print('GEOLOGY_RECOVERY_SHA256='+hashlib.sha256(body).hexdigest())
    print('GEOLOGY_RECOVERY_ZLIB_BASE64='+encoded)
    print('GEOLOGY_RECOVERY_DONE',flush=True)
    assert time.monotonic()-START<60, 'Final output/flush deadline exceeded'

LIAONING_OFFLINE_PARSE
